<?php
require_once __DIR__.'/../../config/config.php';require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../includes/permissions.php';
requireRole(['ADMIN_ETABLISSEMENT','RESPONSABLE_PEDAGOGIQUE']);if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));$pageTitle='Justifications de stage';$activePage='stage-justifications';require_once __DIR__.'/../../includes/app-header.php';
?>
<main class="dashboard-content"><div class="stagia-page-head"><div><h1>Justifications de stage</h1><p>Examinez les situations de non-démarrage ou d’interruption signalées par les étudiants.</p></div></div>
<div class="stagia-kpi-grid"><div class="stagia-kpi-card"><div><span>TOTAL</span><strong id="total">0</strong></div></div><div class="stagia-kpi-card"><div><span>EN ATTENTE</span><strong id="pending">0</strong></div></div><div class="stagia-kpi-card"><div><span>ACCEPTÉES</span><strong id="accepted">0</strong></div></div><div class="stagia-kpi-card"><div><span>REJETÉES</span><strong id="rejected">0</strong></div></div></div>
<div class="card border-0 shadow-sm"><div class="card-body"><div class="d-flex gap-2 flex-wrap mb-3"><input id="search" class="form-control" style="max-width:360px" placeholder="Étudiant, code ou établissement"><select id="status" class="form-select" style="max-width:220px"><option value="">Tous les statuts</option><option>EN_ATTENTE</option><option>ACCEPTEE</option><option>REJETEE</option></select></div><div id="list">Chargement…</div></div></div></main>
<div class="modal fade" id="reviewModal"><div class="modal-dialog"><form id="reviewForm" class="modal-content"><div class="modal-header"><h5 class="modal-title">Décision universitaire</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" id="uuid"><label class="form-label">Décision</label><select id="decision" class="form-select mb-3"><option value="ACCEPTEE">Accepter</option><option value="REJETEE">Rejeter</option></select><label class="form-label">Commentaire</label><textarea id="comment" class="form-control" rows="4" maxlength="4000"></textarea><small class="text-muted">Le commentaire est obligatoire en cas de rejet.</small></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Annuler</button><button class="btn btn-primary-stagia">Enregistrer</button></div></form></div></div>
<script>
const BASE='<?=BASE_URL?>',CSRF='<?=htmlspecialchars($_SESSION['csrf'],ENT_QUOTES)?>';let items=[];const $=id=>document.getElementById(id),modal=new bootstrap.Modal($('reviewModal')),esc=v=>STAGIA.escape(String(v??''));
async function req(url,o={}){const r=await fetch(BASE+url,{credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest'},...o}),j=await r.json();if(!j.success)throw new Error(j.message||'Erreur');return j;}
function badge(s){return s==='ACCEPTEE'?'<span class="badge bg-success">Acceptée</span>':s==='REJETEE'?'<span class="badge bg-danger">Rejetée</span>':'<span class="badge bg-warning text-dark">En attente</span>';}
function render(){const q=$('search').value.toLowerCase(),st=$('status').value;const rows=items.filter(x=>(!st||x.statut===st)&&[x.student_name,x.stagia_code,x.campaign_code,x.campaign_title,x.host_name].join(' ').toLowerCase().includes(q));$('list').innerHTML=rows.length?rows.map(x=>`<article class="border rounded-3 p-3 mb-3"><div class="d-flex justify-content-between gap-3 flex-wrap"><div><div><strong>${esc(x.student_name)}</strong> <small class="text-muted">${esc(x.stagia_code)}</small> ${badge(x.statut)}</div><div class="small text-muted">${esc(x.campaign_code)} — ${esc(x.campaign_title)} · ${esc(x.host_name||'-')}</div><div class="mt-2"><strong>${x.type_situation==='INTERRUPTION'?'Stage interrompu':'Stage non démarré'}</strong> · ${esc(x.motif)}</div>${x.explication?`<p class="mb-1 mt-2">${esc(x.explication)}</p>`:''}${x.decision_commentaire?`<div class="alert alert-light border py-2 mb-0">${esc(x.decision_commentaire)}</div>`:''}</div><div class="d-flex gap-2 align-items-start">${x.document_path?`<a target="_blank" class="btn btn-outline-secondary btn-sm" href="${BASE}/actions/stages/university-stage-justification-file.php?token=${encodeURIComponent(x.uuid)}">Document</a>`:''}${x.statut==='EN_ATTENTE'?`<button class="btn btn-primary-stagia btn-sm" onclick="review('${esc(x.uuid)}')">Décider</button>`:''}</div></div></article>`).join(''):'<div class="text-center py-5 text-muted">Aucune justification.</div>';}
async function load(){try{const r=await req('/actions/stages/university-stage-justification-list.php');items=r.data.items||[];const s=r.data.stats||{};$('total').textContent=s.total||0;$('pending').textContent=s.EN_ATTENTE||0;$('accepted').textContent=s.ACCEPTEE||0;$('rejected').textContent=s.REJETEE||0;render();}catch(e){$('list').innerHTML=`<div class="alert alert-danger">${esc(e.message)}</div>`;}}
window.review=uuid=>{$('reviewForm').reset();$('uuid').value=uuid;modal.show();};$('reviewForm').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData();fd.append('csrf',CSRF);fd.append('uuid',$('uuid').value);fd.append('decision',$('decision').value);fd.append('commentaire',$('comment').value);try{const r=await req('/actions/stages/university-stage-justification-review.php',{method:'POST',body:fd});modal.hide();STAGIA.toast(r.message,'success');load();}catch(err){STAGIA.toast(err.message,'danger');}});$('search').addEventListener('input',render);$('status').addEventListener('change',render);load();
</script><?php require_once __DIR__.'/../../includes/app-footer.php';?>
